//! R036/06: Editor tab ownership and stale revision guard. Real guest filesystem/workstation operation.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX,PATH_MAX};
pub struct Tabs<const N:usize>{owner:u64,opened:[Option<(u64,u64)>;N]}impl<const N:usize> Tabs<N>{pub fn new(owner:u64)->Self{Self{owner,opened:[None;N]}}pub fn open(&mut self,owner:u64,file_id:u64,revision:u64)->Result<usize,Error>{if owner==0||owner!=self.owner{return Err(Error::Denied);}if file_id==0||revision==0{return Err(Error::Invalid);}if let Some(i)=self.opened.iter().position(|o|o.is_some_and(|(id,_)|id==file_id)){return Ok(i);}let slot=self.opened.iter().position(Option::is_none).ok_or(Error::Full)?;self.opened[slot]=Some((file_id,revision));Ok(slot)}pub fn check(&self,owner:u64,slot:usize,revision:u64)->Result<(),Error>{if owner!=self.owner{return Err(Error::Denied);}let (_,expected)=self.opened.get(slot).copied().flatten().ok_or(Error::Missing)?;if revision!=expected{return Err(Error::Stale);}Ok(())}pub fn close(&mut self,owner:u64,slot:usize)->Result<(),Error>{self.check(owner,slot,self.opened.get(slot).copied().flatten().ok_or(Error::Missing)?.1)?;self.opened[slot]=None;Ok(())}}
#[cfg(test)]mod tests{use super::*;#[test]fn real_functional_regression(){let mut t=Tabs::<2>::new(7);let s=t.open(7,99,1).unwrap();assert_eq!(t.check(7,s,2),Err(Error::Stale));assert_eq!(t.check(8,s,1),Err(Error::Denied));t.close(7,s).unwrap();}}
